for(const name of ['deconstruct','normalize','narrative-crisis']) {
 const path=`/v1/query/${name}`;
 add(path,'post',[],{type:'object',properties:{success:{type:'boolean'}},required:['success'],additionalProperties:true});
 body(path,{question:str(1,2000)},['question']);
 paths[path].post.responses['200'].content['application/json'].schema={type:'object',properties:{success:{type:'boolean'},...(name==='normalize'?{original:{type:'string'},normalized:{type:'string'},myth:{type:['object','null'],additionalProperties:true}}:name==='narrative-crisis'?{match:{type:['object','null'],additionalProperties:true}}:{raw:{type:'string'},cleaned:{type:'string'},slots:{type:'object',additionalProperties:true},canonicalIntent:{type:['string','null']},summary:{type:'string'}})},required:['success'],additionalProperties:true};
 paths[path].post.description='Unreviewed query analysis. Static matches do not constitute published evidence.';
}
// Imported catalog operations must not reuse identifiers from other batches.
const operationIds=new Set();
for(const [path,methods] of Object.entries(paths))for(const [method,operation] of Object.entries(methods)) {
 if(operationIds.has(operation.operationId))operation.operationId=`${method}_${path.replace(/[^a-zA-Z0-9]+/g,'_')}`;
 operationIds.add(operation.operationId);
}
for(const path of ['/v1/realtime/simulate','/v1/realtime/poll','/v1/realtime/subscriptions'])for(const operation of Object.values(paths[path])) {
 operation.security=[{bearerAuth:[]}];operation['x-allowed-roles']=['admin'];
}
